      dueDateButton.type = 'submit';
      dueDateButton.disabled = Boolean(readOnly);
      dueDateForm.append(dueDateLabel, dueDateInput, dueDateButton);
      dueDateForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (archived || saving.has(task.id)) return;
        await saveTask({ dueDate: dueDateInput.value.trim() });
      });
      const moveForm = element('form');
      const destinationLabel = element('label', 'Destination project');
      destinationLabel.htmlFor = `destination-project-${task.id}`;
      const destination = element('select');
      destination.id = destinationLabel.htmlFor;
      for (const project of destinations) {
        const option = element('option', project.name);
        option.value = String(project.id);
        destination.append(option);
      }
      const moveButton = element('button', 'Move task');
      moveButton.type = 'submit';
      destination.disabled = moveButton.disabled = Boolean(readOnly) || destinations.length === 0;
      moveForm.append(destinationLabel, destination, moveButton);
      moveForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (moveButton.disabled) return;
        await saveTask({ destinationProjectId: Number(destination.value) });
      });
      const notesForm = element('form');
      const notesLabel = element('label', 'Task notes');
      notesLabel.htmlFor = `task-notes-${task.id}`;
      const notesInput = element('textarea');
      notesInput.id = notesLabel.htmlFor;
      notesInput.name = 'notes';
      notesInput.rows = 4;
      notesInput.value = task.notes || '';
      notesInput.disabled = Boolean(readOnly);
      const notesButton = element('button', 'Save notes');
      notesButton.type = 'submit';
      notesButton.disabled = Boolean(readOnly);
      notesForm.append(notesLabel, notesInput, notesButton);
      notesForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (archived || saving.has(task.id)) return;
        await saveTask({ notes: notesInput.value });
      });
      const deletionButton = element('button', task.deleted ? 'Restore task' : 'Delete task');
      deletionButton.type = 'button';
      deletionButton.disabled = archived || saving.has(task.id);
      deletionButton.addEventListener('click', () => saveTask({ deleted: !task.deleted }));
      row.append(checkbox, element('span', task.title), renameForm, priorityLabel, priority, dueDateForm, moveForm, notesForm, deletionButton);
      return row;
    }));
  }

  filter.addEventListener('change', renderTasks);
  priorityFilter.addEventListener('change', renderTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (create.disabled) return;
    app.querySelector('[role="alert"]')?.remove();
    const title = input.value.trim();
    if (!title) {
      showAlert('Task title is required');
      input.focus();
      return;
    }
    create.disabled = true;
    try {
      const task = await api(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      tasks.push(task);
      renderTasks();
      input.value = '';
      input.focus();
    } catch (error) {
      showAlert(error.message);
    } finally {
      create.disabled = archived;
    }
  });
  app.append(form, filters, rangeForm, search.form, defaultPriorityControl(project), list);
  const [savedTasks, projects] = await Promise.all([api(endpoint), api('/api/projects')]);
  tasks = savedTasks;
  destinations = projects.filter((candidate) => !candidate.archived && candidate.id !== projectId);
  renderTasks();
  create.disabled = archived;
}

function defaultPriorityControl(project) {
  const control = element('div');
  const label = element('label', 'Default task priority');
  label.htmlFor = 'default-task-priority';
  const select = element('select');
  select.id = label.htmlFor;
  for (const value of ['Low', 'Normal', 'High']) {
    const option = element('option', value);
    option.value = value;
    select.append(option);
  }
  select.value = project.defaultTaskPriority;
  select.disabled = project.archived;
  select.addEventListener('change', async () => {
    if (select.disabled) return;
    select.disabled = true;
    app.querySelector('[role="alert"]')?.remove();
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ defaultTaskPriority: select.value }),
      });
      Object.assign(project, saved);
    } catch (error) {
      showAlert(error.message);
    } finally {
      select.value = project.defaultTaskPriority;
      select.disabled = project.archived;
    }
  });
  control.append(label, select);
  return control;
}

function showRenameForm(project, heading) {
  const form = element('form');
  const label = element('label', 'New project name');
  label.htmlFor = 'new-project-name';
  const input = element('input');
  input.id = 'new-project-name';
  input.name = 'name';
  input.type = 'text';
  input.disabled = project.archived;
  const rename = element('button', 'Rename project');
  rename.type = 'submit';
  rename.disabled = project.archived;
  form.append(label, input, rename);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (rename.disabled) return;
    app.querySelector('[role="alert"]')?.remove();
    const name = input.value.trim();
    if (!name) {
      showAlert('Project name is required');
      input.focus();
      return;
    }
    rename.disabled = true;
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      Object.assign(project, saved);
      heading.textContent = project.name;
      document.title = `${project.name} — Workboard`;
      input.value = '';
      input.focus();
    } catch (error) {
      showAlert(error.message);
    } finally {
